matches=list(re.finditer(r'Demo pair 1 (input|output) \(29x29\):\n',txt)); demo={}
for i,m in enumerate(matches):
 end=matches[i+1].start() if i+1<len(matches) else txt.index('\n\nSame instance',m.end())
 body=txt[m.end():end].strip(); lines=body.splitlines(); print(m.group(1),len(lines), lines[-1][:60]); demo[m.group(1)]=np.array([[int(x) for x in line.split()] for line in lines])
A,B=demo['input'],demo['output']; print(A.shape,B.shape,np.sum(B==2),np.sum(A==2),np.sum((B==2)&(A!=2)))

def uniq_transforms(mask):
 out=[]
 for k in range(4):
  x=np.rot90(mask,k)
  for y in (x,np.fliplr(x)):
   if not any(np.array_equal(y,z) for z in out): out.append(y)
 return out
trans=uniq_transforms(mask); print(len(trans),[x.shape for x in trans])
union=np.zeros_like(A,dtype=bool); placements=[]
for ti,t in enumerate(trans):
 h,w=t.shape
 for r in range(30-h):
  for c in range(30-w):
   coords=np.argwhere(t)+[r,c]
   vals=A[coords[:,0],coords[:,1]]
   if np.all((vals==0)|(vals==2)) and np.all(vals[A[coords[:,0],coords[:,1]]!=2]==0):
    # all positions were 0 or initial colored cells
    union[coords[:,0],coords[:,1]]=1; placements.append((ti,r,c))
added=(B==2)&(A!=2)
print('added',added.sum(),'matched union',union.sum(),'intersection',np.sum(added&union),'extra',np.sum(added&~union),'miss',np.sum(union&~(B==2)), 'placements',len(placements))

